export declare abstract class VecBase<T extends VecBase<T>> {
    abstract clone(): T;
    abstract add(v: T): T;
    abstract scale(s: number): T;
    abstract dot(v: T): number;
    abstract toString(): string;
    neg(): T;
    sub(v: T): T;
    addScaled(v: T, s: number): T;
    magSq(): number;
    mag(): number;
    normalize(): T;
    proj(u: T): T;
    print(): void;
}
